<script setup>
import { computed, onMounted, ref } from 'vue'
import Chart from '../components/Chart.vue'
import { api, fmt, models, baseChart, featureLabel } from '../lib/api'
const data = ref(null), error = ref(''), split = ref('test'), horizon = ref(6)
onMounted(async () => { try { data.value = await api('models') } catch (e) { error.value = e.message } })
const runs = computed(() => Object.values(data.value?.registry.runs || {}))
const primary = computed(() => runs.value.filter(r => r.variant === 'regional').flatMap(r => r.metrics.filter(m => m.split === split.value).map(m => ({ ...r, ...m }))))
const best = computed(() => primary.value.find(r => r.model === 'rf' && r.horizon === 6))
const baseline = computed(() => primary.value.find(r => r.model === 'persistence' && r.horizon === 6))
const improvement = computed(() => best.value && baseline.value ? (1 - best.value.rmse / baseline.value.rmse) * 100 : null)
const errorOption = computed(() => ({ ...baseChart, yAxis: { ...baseChart.yAxis, name: 'RMSE · μg/m³' }, xAxis: { ...baseChart.xAxis, type: 'category', data: ['+1 h', '+2 h', '+3 h', '+4 h', '+5 h', '+6 h'] }, legend: { bottom: 0, itemWidth: 15, itemHeight: 8, textStyle: { color: '#7b887f', fontSize: 11 } }, grid: { ...baseChart.grid, bottom: 48 }, series: ['persistence', 'rf', 'gbt'].map((id, i) => ({ name: models[id], type: 'line', symbolSize: 6, lineStyle: { width: id === 'rf' ? 2.8 : 1.7, type: id === 'persistence' ? 'dashed' : 'solid' }, itemStyle: { color: ['#afb4a8', '#176e59', '#d4a160'][i] }, data: Array.from({ length: 6 }, (_, h) => primary.value.find(r => r.model === id && r.horizon === h + 1)?.rmse) })) }))
const ablation = computed(() => ['beijing', 'weather', 'regional'].map(variant => { const r = runs.value.find(r => r.variant === variant && r.model === 'rf' && r.horizon === Number(horizon.value)); return r ? { ...r, ...r.metrics.find(m => m.split === split.value) } : null }))
const ablationOption = computed(() => ({ ...baseChart, grid: { top: 32, left: 50, right: 20, bottom: 40 }, xAxis: { ...baseChart.xAxis, type: 'category', data: ['仅北京污染历史', '加入北京气象', '再加入周边城市'], axisLabel: { fontSize: 10, interval: 0 } }, yAxis: { ...baseChart.yAxis, name: 'RMSE · μg/m³' }, series: [{ type: 'bar', barWidth: '34%', label: { show: true, position: 'top', formatter: p => fmt(p.value, 2), color: '#5a6f61' }, data: ablation.value.map((r, i) => ({ value: r?.rmse, itemStyle: { color: ['#c8d0b5', '#88ab8d', '#176e59'][i], borderRadius: [5, 5, 0, 0] } })) }] }))
const importance = computed(() => runs.value.find(r => r.variant === 'regional' && r.model === 'rf' && r.horizon === Number(horizon.value))?.feature_importance.slice(0, 12).reverse() || [])
const importanceOption = computed(() => ({ ...baseChart, grid: { top: 2, left: 185, right: 40, bottom: 20 }, xAxis: { ...baseChart.xAxis, type: 'value', axisLabel: { formatter: v => `${Math.round(v * 100)}%` } }, yAxis: { type: 'category', data: importance.value.map(r => featureLabel(r.feature)), axisLine: { show: false }, axisTick: { show: false }, axisLabel: { color: '#748077', fontSize: 10, width: 170, overflow: 'truncate' } }, series: [{ type: 'bar', barWidth: 10, data: importance.value.map(r => r.importance), itemStyle: { color: '#71a18a', borderRadius: [0, 3, 3, 0] } }], tooltip: { trigger: 'axis', formatter: ps => `${ps[0].name}<br/>重要性 ${fmt(ps[0].value * 100, 2)}%` } }))
</script>
<template>
  <div v-if="error" class="error-box">{{ error }}</div><div v-if="!data" class="page-loader"><span class="spinner"></span> 正在读取实验结果…</div>
  <template v-else>
    <div class="experiment-timeline"><div><span>TRAIN</span><strong>2015—2023</strong><small>训练特征与模型</small></div><i></i><div><span>VALIDATE</span><strong>2024</strong><small>按时长选择推荐模型</small></div><i></i><div class="active"><span>TEST</span><strong>2025</strong><small>仅用于独立评估</small></div><div class="experiment-engine"><b>Spark ML</b><span>残差回归 · 1–6 小时</span></div></div>
    <div class="view-toolbar"><div class="segmented"><button :class="{ active: split === 'test' }" @click="split = 'test'">2025 独立测试</button><button :class="{ active: split === 'validation' }" @click="split = 'validation'">2024 模型验证</button></div><span class="quiet">指标越低越好 · 不使用测试集选择模型</span></div>
    <section class="kpi-grid three"><article class="kpi-card featured"><div class="kpi-label">随机森林 · 6 小时 RMSE</div><div class="kpi-number">{{ fmt(best?.rmse, 2) }}<small>μg/m³</small></div><div class="kpi-bottom">{{ fmt(best?.n, 0) }} 个同条件评估样本</div></article><article class="kpi-card"><div class="kpi-label">相比持续性基线</div><div class="kpi-number">{{ fmt(improvement) }}<small>% RMSE 降低</small></div><div class="kpi-bottom">基线 RMSE {{ fmt(baseline?.rmse, 2) }} μg/m³</div></article><article class="kpi-card"><div class="kpi-label">特征组合实验</div><div class="kpi-number">03<small>组输入</small></div><div class="kpi-bottom">污染历史 → 气象 → 周边城市</div></article></section>
    <div class="two-column-grid"><section class="panel"><div class="panel-heading"><div><div class="section-kicker">MODEL COMPARISON</div><h2>预测越远，误差如何变化？</h2></div></div><Chart :option="errorOption" height="300px" label="三种预测模型在不同预测时长上的RMSE对比" /></section><section class="panel"><div class="panel-heading"><div><div class="section-kicker">FEATURE ABLATION</div><h2>周边信息是否带来帮助？</h2></div><select v-model.number="horizon" class="compact-select" aria-label="消融实验预测时长"><option :value="1">未来 1 小时</option><option :value="3">未来 3 小时</option><option :value="6">未来 6 小时</option></select></div><Chart :option="ablationOption" height="300px" label="三组输入特征的随机森林模型RMSE对比" /><div class="panel-note">固定随机森林算法与参数，比较同一评估样本上的误差。</div></section></div>
    <div class="two-column-grid"><section class="panel"><div class="panel-heading"><div><div class="section-kicker">FEATURE IMPORTANCE</div><h2>模型关注哪些信息？</h2></div><span class="subtle-tag">随机森林 · +{{ horizon }} h</span></div><Chart :option="importanceOption" height="350px" label="随机森林模型的前十二项特征重要性" /><div class="panel-note">树模型特征重要性用于解释模型分裂贡献，不代表因果影响。</div></section><section class="panel"><div class="panel-heading"><div><div class="section-kicker">EVALUATION DETAILS</div><h2>逐模型评估结果</h2></div></div><div class="table-scroll evaluation-table"><table><thead><tr><th>模型 / 时长</th><th class="numeric">MAE</th><th class="numeric">RMSE</th><th class="numeric">样本</th></tr></thead><tbody><tr v-for="r in [...primary].sort((a,b) => a.horizon-b.horizon)" :key="`${r.model}-${r.horizon}`"><td>{{ models[r.model] }} <span class="muted-text">+{{ r.horizon }}h</span></td><td class="numeric">{{ fmt(r.mae, 2) }}</td><td class="numeric" :class="{ 'strong-value': r.model === 'rf' }">{{ fmt(r.rmse, 2) }}</td><td class="numeric muted-text">{{ fmt(r.n, 0) }}</td></tr></tbody></table></div></section></div>
    <div class="method-note"><p>各时长单独训练。训练时排除跨年度边界的标签，缺失特征用训练集的中位数处理；验证与测试沿用该处理器。推荐模型仅依据 2024 年验证集 RMSE 选取，即使其他模型在测试集更好，也不据此更换推荐结果。</p></div>
  </template>
</template>
